INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (149, 1, 'main..feature 읽기', '`git log --oneline main..feature` 는 어떤 커밋을 보여 줄까요?', '점 두 개는 "왼쪽에는 없고 오른쪽에는 있는"을 뜻해요.', NULL, NULL, '[]', 'choice', '["`main` 에는 있고 `feature` 에는 없는 커밋", "두 브랜치에 모두 있는 커밋", "`feature` 에는 있고 `main` 에는 없는 커밋", "두 브랜치의 모든 커밋"]', 2, '합치기 전에 "이 브랜치가 무엇을 더하는지" 확인할 때 씁니다. 방향을 바꿔 `feature..main` 으로 쓰면 반대로 보여 줘요.', NULL, NULL, NULL, NULL),
  (149, 2, 'log 필터', '특정 사람이 만든 커밋만 보려면 어떻게 할까요?', 'log 에 조건을 붙여요.', NULL, NULL, '[]', 'choice', '["`git log --user=이름`", "`git log --author=이름`", "`git filter 이름`", "`git blame 이름`"]', 1, '`--since="1 week ago"` 로 기간을, `-3` 으로 개수를 정할 수도 있습니다. 조건을 여럿 합쳐 쓸 수 있어요.', NULL, NULL, NULL, NULL),
  (149, 3, '특정 파일의 이력', '`git log --oneline -- notes.txt` 에서 `--` 뒤의 `notes.txt` 는 무엇을 뜻할까요?', '파일 경로를 구분해서 알려 줘요.', NULL, NULL, '[]', 'choice', '["그 파일을 바꾼 커밋만 보겠다는 경로 지정", "브랜치 이름", "커밋 메시지에 들어 있는 글자", "삭제할 파일"]', 0, '`--` 는 앞의 옵션과 뒤의 경로를 구분합니다. 파일 이름이 브랜치 이름과 같아도 헷갈리지 않아요.', NULL, NULL, NULL, NULL),
  (149, 4, 'log --stat', '`git log --stat` 은 무엇을 더 보여 줄까요?', '커밋마다 변경 규모를 요약해요.', NULL, NULL, '[]', 'choice', '["커밋의 전체 코드 내용", "커밋을 올린 시각만", "원격 저장소의 주소", "커밋마다 어떤 파일이 몇 줄 바뀌었는지 요약"]', 3, '`-p` 를 쓰면 실제 변경 내용까지 보여 줍니다. 먼저 `--stat` 으로 규모를 보고 필요할 때 `-p` 로 들어가는 것이 편해요.', NULL, NULL, NULL, NULL),
  (149, 5, 'diff 의 세 가지', '`add` 한 변경(`app.py`)과 `add` 하지 않은 변경(`notes.txt`)이 함께 있습니다. `git diff HEAD` 는 무엇을 보여 줄까요?', 'HEAD 는 마지막 커밋이에요.', NULL, NULL, '[]', 'choice', '["add 하지 않은 변경만", "add 한 변경만", "마지막 커밋과 비교해 add 한 변경과 add 하지 않은 변경을 모두 보여 준다", "원격 저장소와의 차이"]', 2, '`git diff` 는 add 하지 않은 변경, `git diff --staged` 는 add 한 변경, `git diff HEAD` 는 둘 다 보여 줍니다.', NULL, NULL, NULL, NULL),
  (149, 6, '두 브랜치 비교', '`git diff main feature` 는 무엇을 보여 줄까요?', '두 지점의 내용 차이예요.', NULL, NULL, '[]', 'choice', '["`main` 에 합쳐진 커밋 목록", "`main` 과 `feature` 의 파일 내용 차이", "두 브랜치가 갈라진 시각", "삭제할 브랜치 목록"]', 1, '`log main..feature` 는 "커밋 목록", `diff main feature` 는 "내용 차이"입니다. 합치기 전에 두 가지를 함께 보면 좋아요.', NULL, NULL, NULL, NULL),
  (149, 7, 'restore 로 변경 버리기', '`git restore app.py` 는 무엇을 할까요?', 'add 하지 않은 변경을 마지막 커밋 상태로 되돌려요.', NULL, NULL, '[]', 'choice', '["`add` 하지 않은 변경을 버리고 마지막 커밋 상태로 되돌린다 (버린 변경은 복구할 수 없다)", "변경을 스테이징 영역에 올린다", "파일을 삭제한다", "변경을 stash 에 보관한다"]', 0, '커밋하지 않은 변경은 Git 이 기억하지 않으니 버리기 전에 `git diff` 로 확인하세요. 스테이징만 취소하려면 `--staged` 를 쓰세요.', NULL, NULL, NULL, NULL),
  (149, 8, 'git clean -n', '`git clean -n` 은 무엇을 할까요?', 'n 은 "실제로는 하지 않고 보여 주기만"이에요.', NULL, NULL, '[]', 'choice', '["추적하지 않는 파일을 바로 삭제한다", "추적하는 파일을 삭제한다", "저장소를 초기화한다", "추적하지 않는 파일 중 지워질 목록만 보여 주고 실제로는 지우지 않는다 (시험 실행)"]', 3, '실제로 지우려면 `-f` 가 필요합니다. 항상 `-n` 으로 목록을 먼저 확인한 뒤 `-f` 를 쓰세요.', NULL, NULL, NULL, NULL),
  (149, 9, 'rm 과 rm --cached', '`git rm keep.txt` 와 `git rm --cached keep.txt` 의 차이로 알맞은 것은 무엇일까요?', '`--cached` 는 저장소 쪽만 건드려요.', NULL, NULL, '[]', 'choice', '["둘은 완전히 같다", "`--cached` 는 파일을 삭제하고 `rm` 은 추적만 끊는다", "`rm` 은 파일을 삭제하고 그 삭제를 스테이징하며, `--cached` 는 Git 의 추적만 끊고 파일은 그대로 둔다", "둘 다 원격 저장소의 파일을 삭제한다"]', 2, '이미 올린 비밀 설정 파일을 추적에서 빼고 싶을 때 `--cached` 를 쓰고 `.gitignore` 에 적습니다.', NULL, NULL, NULL, NULL),
  (149, 10, 'git mv', '`git mv old.py new.py` 는 어떤 점이 좋을까요?', '이름 변경을 Git 에게 알리는 방법이에요.', NULL, NULL, '[]', 'choice', '["파일의 내용도 자동으로 새로 쓴다", "이름 변경을 한 번에 처리하고 스테이징해서 이력에서 이름이 바뀐 것으로 이어서 볼 수 있다", "원격 저장소의 파일 이름을 바꾼다", "이전 이력이 사라진다"]', 1, '그냥 `mv` 로 바꿔도 Git 이 보통 이름 변경으로 인식하지만, `git mv` 는 확실하게 스테이징까지 해 줍니다.', NULL, NULL, NULL, NULL),
  (149, 11, 'stash 가 담는 것', '`git stash` 를 실행하면 어떤 변경이 보관될까요?', '새로 만든 파일도 담기는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["추적 중인 파일의 변경만 보관한다 (새로 만든 파일은 `-u` 를 붙여야 함께 보관된다)", "새로 만든 파일을 포함해 모든 변경을 보관한다", "커밋된 변경도 보관한다", "원격 저장소의 변경을 보관한다"]', 0, '새 파일이 stash 되지 않고 남아 있는 것에 놀라는 경우가 흔합니다. `git stash -u` 로 함께 보관하세요.', NULL, NULL, NULL, NULL),
  (149, 12, 'stash pop 과 apply', '`git stash pop` 과 `git stash apply` 의 차이로 알맞은 것은 무엇일까요?', '하나는 꺼내서 지우고, 하나는 꺼내도 남겨 둬요.', NULL, NULL, '[]', 'choice', '["둘은 완전히 같다", "`apply` 는 보관함에서 삭제하고 `pop` 은 남긴다", "둘 다 보관함을 비운다", "`pop` 은 변경을 적용하고 보관함에서 삭제하며, `apply` 는 적용하되 보관함에 그대로 남긴다"]', 3, '같은 변경을 여러 브랜치에 적용하고 싶다면 `apply` 를 쓰고, 다 쓴 뒤에는 `git stash drop` 으로 지웁니다.', NULL, NULL, NULL, NULL),
  (149, 13, 'push -u 의 의미', '`git push -u origin feature` 에서 `-u` 는 무엇을 할까요?', '이 브랜치와 원격 브랜치를 이어 줘요.', NULL, NULL, '[]', 'choice', '["강제로 덮어쓴다", "원격의 브랜치를 삭제한다", "로컬 `feature` 와 원격 `origin/feature` 를 연결해 다음부터는 `git push`, `git pull` 만으로 쓸 수 있게 한다", "커밋을 합친다"]', 2, '연결되면 `git branch -vv` 에 `[origin/feature]` 가 보이고, `git status` 에 원격보다 몇 커밋 앞서 있는지 나옵니다. 처음 한 번만 하면 돼요.', NULL, NULL, NULL, NULL),
  (149, 14, 'git bisect', '`git bisect` 는 어떤 일에 쓰는 도구일까요?', '이진 탐색(반씩 나눠 찾기)을 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["브랜치를 둘로 나눈다", "문제가 생긴 커밋을 정상(good)과 비정상(bad) 사이에서 반씩 나눠 가며 찾아낸다", "커밋 이력을 압축한다", "충돌을 자동으로 해결한다"]', 1, '커밋이 수십 개여도 몇 번의 확인만으로 "어느 커밋부터 깨졌는지" 찾을 수 있습니다. 끝나면 `git bisect reset` 으로 원래 위치로 돌아와요.', NULL, NULL, NULL, NULL),
  (149, 15, '브랜치 사이 범위', '`feature` 에만 있는 커밋을 보려는 범위입니다. 빈칸을 채우세요.', '점 두 개로 이어요.', NULL, NULL, '[]', 'fill', '["main..feature", "main-feature", "main>feature", "feature<main"]', NULL, '왼쪽은 기준, 오른쪽은 비교 대상입니다. 방향을 바꾸면 결과도 반대가 돼요.', '[0]', 'git log --oneline {0}', NULL, NULL),
  (149, 16, '작성자로 거르기', '특정 작성자의 커밋만 보는 옵션입니다. 빈칸을 채우세요.', '"글쓴이"를 뜻하는 영어 단어예요.', NULL, NULL, '[]', 'fill', '["--author", "--user", "--name", "--who"]', NULL, '이름의 일부만 써도 찾습니다. `--since` 와 함께 쓰면 "최근 일주일 동안 kim 의 커밋"처럼 좁힐 수 있어요.', '[0]', 'git log {0}=kim', NULL, NULL),
  (149, 17, '모든 변경을 마지막 커밋과 비교', 'add 한 변경과 하지 않은 변경을 **모두** 마지막 커밋과 비교하는 대상을 채우세요.', '마지막 커밋을 가리키는 이름이에요.', NULL, NULL, '[]', 'fill', '["HEAD", "--all", "--last", "--both"]', NULL, '`git diff` 만 쓰면 add 하지 않은 변경만 보입니다. `HEAD` 를 붙이면 전부 비교해요.', '[0]', 'git diff {0}', NULL, NULL),
  (149, 18, '변경 버리기', '`add` 하지 않은 `app.py` 의 **변경을 버리는** 명령입니다. 빈칸을 채우세요.', '"복원하다"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["restore", "undo", "reset-file", "discard"]', NULL, '버린 변경은 복구할 수 없습니다. 실행하기 전에 `git diff app.py` 로 확인하세요.', '[0]', 'git {0} app.py', NULL, NULL),
  (149, 19, '지울 파일 미리 보기', '`git clean` 으로 **지워질 파일의 목록만** 보는 옵션입니다. 빈칸을 채우세요.', '"시험 삼아 해 보기"라는 뜻이에요.', NULL, NULL, '[]', 'fill', '["-n", "-f", "-x", "-q"]', NULL, '`-f` 는 실제로 지웁니다. 먼저 `-n` 으로 목록을 확인하세요.', '[0]', 'git clean {0}', NULL, NULL),
  (149, 20, '추적만 끊기', '`keep.txt` 를 **파일은 남기고 추적만 끊는** 옵션입니다. 빈칸을 채우세요.', '"캐시"라는 뜻의 영어 단어가 들어가요.', NULL, NULL, '[]', 'fill', '["--cached", "--keep", "--soft", "--stay"]', NULL, '추적을 끊은 뒤에는 `.gitignore` 에 적어 다시 올라가지 않게 하세요.', '[0]', 'git rm {0} keep.txt', NULL, NULL),
  (149, 21, '파일 이름 바꾸기', '`old.py` 를 `new.py` 로 **이름을 바꾸는** Git 명령입니다. 빈칸을 채우세요.', '리눅스의 파일 이동 명령과 같은 이름이에요.', NULL, NULL, '[]', 'fill', '["mv", "move", "rename", "cp"]', NULL, '이름 변경과 스테이징이 한 번에 처리됩니다.', '[0]', 'git {0} old.py new.py', NULL, NULL),
  (149, 22, '새 파일도 함께 보관', '`git stash` 할 때 **새로 만든 파일도 함께** 보관하는 옵션입니다. 빈칸을 채우세요.', 'untracked 의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-u", "-t", "-n", "-x"]', NULL, '옵션이 없으면 새 파일은 작업 폴더에 그대로 남습니다.', '[0]', 'git stash {0}', NULL, NULL),
  (149, 23, '적용하되 보관함에 남기기', '보관한 변경을 **적용하되 보관함에는 남겨 두는** 명령입니다. 빈칸을 채우세요.', '"적용하다"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["apply", "copy", "keep", "peek"]', NULL, '다 쓴 보관 내용은 `git stash drop` 으로 지웁니다. `pop` 은 적용과 삭제를 한 번에 해요.', '[0]', 'git stash {0}', NULL, NULL),
  (149, 24, '업스트림 연결하며 올리기', '새 브랜치를 올리면서 원격 브랜치와 **연결**하는 옵션입니다. 빈칸을 채우세요.', 'upstream 의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-u", "-f", "-a", "-d"]', NULL, '`-f` 는 강제로 덮어쓰는 위험한 옵션이라 혼동하면 안 됩니다. 연결은 처음 한 번만 하면 돼요.', '[0]', 'git push {0} origin feature', NULL, NULL),
  (149, 25, 'tracked 파일만 한 번에 커밋', '추적 중인 파일의 변경을 **add 와 커밋을 한 번에** 하는 옵션 조합입니다. 빈칸을 채우세요.', '`-a` 와 `-m` 을 붙여요.', NULL, NULL, '[]', 'fill', '["-am", "-m", "-a", "-A"]', NULL, '`-a` 는 이미 추적 중인 파일만 대상이라 새 파일은 따로 `git add` 해야 합니다.', '[0]', 'git commit {0} "메시지"', NULL, NULL),
  (149, 26, '하던 작업을 치우고 급한 수정하기', '하던 작업을 잠시 치우고 다른 브랜치에서 급한 수정을 한 뒤 돌아오는 순서입니다. 순서에 맞게 놓아 보세요.', '보관 → 이동·수정 → 돌아오기 → 꺼내기 순서예요.', NULL, NULL, '[]', 'order', '["`git stash` 로 하던 작업을 잠시 보관한다", "`git switch main` 으로 이동해 급한 수정을 하고 커밋한다", "`git switch -` 로 원래 브랜치로 돌아온다", "`git stash pop` 으로 보관한 작업을 꺼내 이어서 한다"]', NULL, '`git switch -` 는 바로 전에 있던 브랜치로 돌아가는 단축 명령입니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (149, 27, '새 브랜치를 원격에 올리고 연결하기', '새 브랜치를 만들어 원격에 올리고 연결을 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 커밋 → 올리며 연결 → 확인 순서예요.', NULL, NULL, '[]', 'order', '["`git switch -c feature` 로 브랜치를 만든다", "파일을 고치고 `git add`, `git commit` 으로 기록한다", "`git push -u origin feature` 로 올리면서 연결한다", "`git branch -vv` 로 `[origin/feature]` 연결을 확인한다"]', NULL, '연결한 뒤에는 `git push` 만 입력해도 같은 브랜치로 올라갑니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (149, 28, '추적하지 않는 파일 안전하게 정리', '추적하지 않는 파일을 안전하게 정리하는 순서입니다. 순서에 맞게 놓아 보세요.', '확인 → 시험 → 실제 삭제 → 다시 확인 순서예요.', NULL, NULL, '[]', 'order', '["`git status` 로 추적하지 않는 파일(`??`)을 확인한다", "`git clean -n` 으로 지워질 목록을 미리 본다", "목록이 맞으면 `git clean -f` 로 실제로 삭제한다", "`git status` 로 깨끗해졌는지 확인한다"]', NULL, '`clean` 으로 지운 파일은 Git 이 기억하지 않아 복구가 어렵습니다. 시험 실행을 건너뛰지 마세요.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (149, 29, '언제부터 깨졌는지 bisect 로 찾기', '어느 커밋부터 문제가 생겼는지 찾는 순서입니다. 순서에 맞게 놓아 보세요.', '시작 → 나쁜 지점 → 좋은 지점 → 마무리 순서예요.', NULL, NULL, '[]', 'order', '["`git bisect start` 로 탐색을 시작한다", "`git bisect bad` 로 지금 상태가 나쁘다고 알린다", "`git bisect good 커밋` 으로 정상이었던 커밋을 알린다", "찾아낸 커밋을 확인하고 `git bisect reset` 으로 원래대로 돌아온다"]', NULL, 'Git 이 중간 커밋으로 이동해 주면 테스트한 뒤 `good` 또는 `bad` 로 알려 주는 일을 반복합니다. 끝나면 꼭 `reset` 하세요.', '[0, 1, 2, 3]', NULL, NULL, NULL);
